referenceSolutionTemplate:
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] 条数们 = new int[n];
        for (int i = 0; i < n; i++) {
            条数们[i] = sc.nextInt();
        }

        Path 门牌 = Path.of("账本.txt");

        Files.writeString(门牌, "第 1 笔：" + 条数们[0] + " 条\n");
        for (int i = 1; i < n; i++) {
            Files.writeString(门牌, "第 " + (i + 1) + " 笔：" + 条数们[i] + " 条\n", StandardOpenOption.APPEND);
        }

        System.out.println("在不在：" + Files.exists(门牌));
        System.out.println("几个字节：" + Files.size(门牌));
        System.out.print(Files.readString(门牌));
    }
}
